namespace {
NativeSceneNode* Find(const std::unordered_map<std::string,NativeSceneNode*>& nodes,const std::string& name){auto it=nodes.find(name);return it==nodes.end()?nullptr:it->second;}
std::string SourceName(std::string name){size_t at=0;while((at=name.find("f_t_",at))!=std::string::npos){name.replace(at,4,"f_pv_");at+=5;}return name;}
float InverseLerp(float a,float b,float value){return a==b?0:std::clamp((value-a)/(b-a),0.f,1.f);}
Vector3 AtDistance(Vector3 point,Vector3 anchor,float length){return anchor+Unit(point-anchor)*length;}
Quaternion Plane(Vector3 a,Vector3 b,Vector3 c){return LookRotation(b-a,c-a);}
Quaternion RotationInPlane(Quaternion bone,Quaternion plane){return Inverse(Mul(Inverse(bone),plane));}
}
struct NativeIdleLimbs::Impl {
    struct Limb {NativeSceneNode *Upper{},*Lower{},*End{},*Target{},*Bend{},*TargetSource{},*BendSource{},*Shoulder{};Vector3 LocalBend{},ShoulderAxis{},A{},B{},C{};Quaternion UpperFrame{},LowerFrame{};float First=0,Second=0,RootLength=0,Pull=0;};
    struct Link {size_t A=0,B=0;float Length=0,Push=0,Pull=0,Share=0;};
    struct Spine {NativeSceneNode* Bone{};Vector3 Point{},Swing{},Twist{};float Length=0;};
    std::vector<Limb> Limbs;std::vector<Link> Links;std::vector<Spine> Spines;NativeSceneNode *Root{},*Rig{};int BodyIterations=0,SpineIterations=0,SpineRoot=-1;float PullVertical=0,PullHorizontal=0,TwistWeight=0,Pin=0;
    std::unordered_map<NativeSceneNode*,Vector3> DefaultPositions;std::unordered_map<NativeSceneNode*,Quaternion> DefaultRotations;
    Impl(const Parameter& component,const std::unordered_map<std::string,NativeSceneNode*>& bones,const std::unordered_map<std::string,NativeSceneNode*>& rest,std::vector<std::string>& diagnostics){
        auto& solver=component.Get("solver");if(solver.Float("IKPositionWeight",1)<=0)return;Root=Find(bones,solver.String("rootNode"));Rig=Find(bones,solver.String("root"));BodyIterations=std::clamp(static_cast<int>(solver.Float("iterations",4)),0,64);PullVertical=solver.Float("pullBodyVertical",.5f);PullHorizontal=solver.Float("pullBodyHorizontal");Pin=At(solver.Get("chain"),0).Float("pin");size_t index=0;
        for(auto& map:solver.Get("limbMappings").Children){size_t chainIndex=++index;Limb limb;limb.Upper=Find(bones,map.String("bone1"));limb.Lower=Find(bones,map.String("bone2"));limb.End=Find(bones,map.String("bone3"));if(map.Float("weight",1)<=0||!limb.Upper||!limb.Lower||!limb.End)continue;auto& effectors=solver.Get("effectors").Children;auto effector=std::find_if(effectors.begin(),effectors.end(),[&](auto& e){return e.String("bone")==limb.End->Name;});auto& chain=At(solver.Get("chain"),chainIndex);auto bendName=chain.Get("bendConstraint").String("bendGoal");if(effector!=effectors.end()){limb.Target=Find(bones,effector->String("target"));limb.TargetSource=Find(bones,SourceName(effector->String("target")));}limb.Bend=Find(bones,bendName);limb.BendSource=Find(bones,SourceName(bendName));if(!limb.Target||!limb.TargetSource||!limb.Bend||!limb.BendSource){diagnostics.push_back("待机 IK 缺少原始动作目标："+limb.End->Name);continue;}limb.Shoulder=Find(bones,map.String("parentBone"));auto* ra=Find(rest,limb.Upper->Name);auto* rb=Find(rest,limb.Lower->Name);auto* rc=Find(rest,limb.End->Name);Require(ra&&rb&&rc,"Idle IK rest bone is missing.");auto direction=rb->Position()-ra->Position(),axis=rc->Position()-ra->Position();OrthoNormalize(axis,direction);axis=rb->Position()-ra->Position();OrthoNormalize(axis,direction);limb.LocalBend=Rotate(Inverse(ra->Rotation()),direction);limb.Pull=chain.Float("pull",1);limb.First=Length(rb->Position()-ra->Position());limb.Second=Length(rc->Position()-rb->Position());if(limb.Shoulder){auto* shoulder=Find(rest,limb.Shoulder->Name);Require(shoulder,"Idle IK shoulder rest bone is missing.");limb.ShoulderAxis=Rotate(Inverse(shoulder->Rotation()),ra->Position()-shoulder->Position());}Limbs.push_back(limb);}
        for(auto& item:At(solver.Get("chain"),0).Get("childConstraints").Children){auto a=std::find_if(Limbs.begin(),Limbs.end(),[&](auto& l){return l.Upper->Name==item.String("bone1");}),b=std::find_if(Limbs.begin(),Limbs.end(),[&](auto& l){return l.Upper->Name==item.String("bone2");});if(a==Limbs.end()||b==Limbs.end())continue;float push=Links.size()<2?1:item.Float("pushElasticity"),pull=item.Float("pullElasticity");Links.push_back({static_cast<size_t>(a-Limbs.begin()),static_cast<size_t>(b-Limbs.begin()),0,push,pull,push<=0&&pull<=0?static_cast<float>(.5-(double(a->Pull)-b->Pull)*.5):.5f});}
        auto& mapping=solver.Get("spineMapping");for(auto& p:mapping.Get("spineBones").Children)if(auto* bone=Find(bones,p.Text)){if(bone==Root)SpineRoot=static_cast<int>(Spines.size());Spines.push_back({bone});}SpineIterations=std::clamp(static_cast<int>(mapping.Float("iterations",3)),0,64);TwistWeight=mapping.Float("twistWeight",1);
        auto rotation=[&](NativeSceneNode* bone){if(bone)if(auto* source=Find(rest,bone->Name))DefaultRotations[bone]=source->LocalRotation();};for(auto& spine:Spines)rotation(spine.Bone);for(auto& limb:Limbs)for(auto* bone:{limb.Upper,limb.Lower,limb.End,limb.Shoulder})rotation(bone);auto position=[&](NativeSceneNode* bone){if(auto* source=Find(rest,bone->Name))DefaultPositions[bone]=source->LocalPosition();};if(!Spines.empty()){position(Spines.front().Bone);position(Spines.back().Bone);}for(auto& limb:Limbs)position(limb.Upper);
    }
    void RestoreInputPose(){for(auto& [bone,value]:DefaultPositions)bone->LocalPosition(value);for(auto& [bone,value]:DefaultRotations)bone->LocalRotation(value);}
    static void BendLimit(Limb& limb){auto normal=Rotate(limb.Upper->Rotation(),-limb.LocalBend),from=limb.End->Position()-limb.Lower->Position();auto endRotation=limb.End->Rotation();float fraction=static_cast<float>(1-double(Angle(normal,from))/180.f);constexpr float clamp=.505f;if(fraction<=clamp){float blend=std::clamp(fraction/clamp,0.f,1.f)*std::clamp(static_cast<float>(1-(double(clamp)-fraction)/(1-double(fraction))),0.f,1.f);limb.Lower->Rotation(Mul(FromTo(from,Slerp(normal,from,blend)),limb.Lower->Rotation()));}auto axis=limb.Lower->Position()-limb.Upper->Position(),tangent=limb.End->Position()-limb.Lower->Position();OrthoNormalize(axis,tangent);limb.Lower->Rotation(Lerp(limb.Lower->Rotation(),Mul(FromTo(tangent,normal),limb.Lower->Rotation()),1));limb.End->Rotation(endRotation);}
    static void Triangle(Limb& limb,bool goal){auto direction=limb.C-limb.A;float distance=Length(direction);if(distance<1e-8f)return;float safe=std::min(distance,static_cast<float>((double(limb.First)+limb.Second)*.99999f));auto bend=(goal?limb.Bend->Position():limb.B)-limb.A;if(goal)bend=Unit(bend);float square=limb.First*limb.First,difference=static_cast<float>(square-double(limb.Second)*limb.Second),along=static_cast<float>((double(safe)*safe+difference)/2.f/safe),height=static_cast<float>(std::sqrt(std::max(0.f,static_cast<float>(square-double(along)*along))));limb.B=limb.A+Rotate(LookRotation(direction/distance*safe,bend),{0,height,along});}
    void ConstrainLinks(){for(auto& link:Links){auto delta=Limbs[link.B].A-Limbs[link.A].A;float distance=Length(delta);if(distance<1e-8f)continue;float strength=1-(distance>link.Length?link.Pull:link.Push);auto correction=delta*static_cast<float>((1-double(link.Length)/distance)*strength);Limbs[link.A].A+=correction*link.Share;Limbs[link.B].A-=correction*(1-link.Share);}}
    static void ConstrainRoot(Limb& limb,Vector3 anchor){auto delta=limb.A-anchor;float distance=Length(delta);if(distance!=0&&distance!=limb.RootLength)limb.A-=delta*static_cast<float>(1-double(limb.RootLength)/distance);}
    void Step(){if(Limbs.size()!=4||!Root||Spines.size()<2||SpineRoot<0)return;for(auto& limb:Limbs){limb.Target->Position(limb.TargetSource->Position());limb.Target->Rotation(limb.TargetSource->Rotation());limb.Bend->Position(limb.BendSource->Position());limb.Bend->Rotation(limb.BendSource->Rotation());}Vector3 armOffset{};for(int i=0;i<2;++i){auto& limb=Limbs[i];auto delta=limb.Target->Position()-(limb.Upper->Position()+armOffset);float excess=static_cast<float>(double(Length(delta))-limb.First-limb.Second);if(excess>0)armOffset+=Unit(delta)*excess;}auto up=Rig?Rig->TransformDirection({0,1,0}):Vector3{0,1,0},vertical=up*Dot(up,armOffset),bodyOffset=vertical*PullVertical+(armOffset-vertical)*PullHorizontal;for(auto& limb:Limbs)BendLimit(limb);
        for(auto& limb:Limbs){limb.A=limb.Upper->Position();limb.B=limb.Lower->Position();limb.C=limb.End->Position();limb.First=Length(limb.B-limb.A);limb.Second=Length(limb.C-limb.B);limb.RootLength=Length(limb.A-Root->Position());limb.UpperFrame=RotationInPlane(limb.Upper->Rotation(),Plane(limb.A,limb.B,limb.C));limb.LowerFrame=RotationInPlane(limb.Lower->Rotation(),Plane(limb.B,limb.C,limb.A));}for(auto& link:Links)link.Length=Length(Limbs[link.A].A-Limbs[link.B].A);auto oldRoot=Root->Position(),solvedRoot=oldRoot+bodyOffset;Limbs[2].A+=bodyOffset;Limbs[3].A+=bodyOffset;float sum=0;for(auto& limb:Limbs)sum+=limb.Pull;sum=std::max(1.f,sum);auto lowPlane=Plane(oldRoot,Limbs[2].Upper->Position(),Limbs[3].Upper->Position()),highPlane=Plane(oldRoot,Limbs[0].Upper->Position(),Limbs[1].Upper->Position());auto hipOffset=Rotate(Inverse(lowPlane),Spines.front().Bone->Position()-oldRoot),neckOffset=Rotate(Inverse(highPlane),Spines.back().Bone->Position()-oldRoot);auto hipRotation=RotationInPlane(Spines.front().Bone->Rotation(),lowPlane),neckRotation=RotationInPlane(Spines.back().Bone->Rotation(),highPlane);
        for(size_t i=0;i+1<Spines.size();++i){auto& spine=Spines[i];auto delta=Spines[i+1].Bone->Position()-spine.Bone->Position();spine.Length=Length(delta);spine.Swing=Rotate(Inverse(spine.Bone->Rotation()),delta);auto twist=Limbs[0].Upper->Position()-Limbs[1].Upper->Position();OrthoNormalize(delta,twist);spine.Twist=Rotate(Inverse(spine.Bone->Rotation()),twist);}
        for(int iteration=0;iteration<BodyIterations;++iteration){for(auto& limb:Limbs){limb.C=limb.Target->Position();Triangle(limb,false);limb.B=AtDistance(limb.B,limb.C,limb.Second);limb.A=AtDistance(limb.A,limb.B,limb.First);}ConstrainLinks();auto candidate=solvedRoot;for(auto& limb:Limbs)candidate+=(AtDistance(solvedRoot,limb.A,limb.RootLength)-solvedRoot)*(limb.Pull/sum);solvedRoot=Lerp(candidate,solvedRoot,Pin);for(int pass=0;pass<std::clamp(BodyIterations,2,4);++pass){ConstrainLinks();for(auto& limb:Limbs)ConstrainRoot(limb,solvedRoot);}for(auto& limb:Limbs){limb.A=AtDistance(limb.A,solvedRoot,limb.RootLength);limb.B=AtDistance(limb.B,limb.A,limb.First);limb.C=AtDistance(limb.C,limb.B,limb.Second);}}
        for(auto& limb:Limbs){limb.C=limb.Target->Position();Triangle(limb,true);}lowPlane=Plane(solvedRoot,Limbs[2].A,Limbs[3].A);highPlane=Plane(solvedRoot,Limbs[0].A,Limbs[1].A);auto bottom=solvedRoot+Rotate(lowPlane,hipOffset),top=solvedRoot+Rotate(highPlane,neckOffset),spineOffset=solvedRoot-oldRoot;for(auto& spine:Spines)spine.Point=spine.Bone->Position()+spineOffset;
        for(int pass=0;pass<SpineIterations;++pass){Spines.back().Point=top;for(int i=static_cast<int>(Spines.size())-2;i>=0;--i)Spines[i].Point=AtDistance(Spines[i].Point,Spines[i+1].Point,Spines[i].Length);Spines.front().Point=bottom;for(size_t i=1;i<Spines.size();++i)Spines[i].Point=AtDistance(Spines[i].Point,Spines[i-1].Point,Spines[i-1].Length);Spines[SpineRoot].Point=solvedRoot;}
        Spines.back().Point=top;Spines.front().Bone->Position(bottom);Spines.front().Bone->Rotation(Mul(lowPlane,hipRotation));for(size_t i=1;i+1<Spines.size();++i){auto& spine=Spines[i];spine.Bone->Rotation(Mul(FromTo(Rotate(spine.Bone->Rotation(),spine.Swing),Spines[i+1].Point-spine.Bone->Position()),spine.Bone->Rotation()));auto axis=Spines[i+1].Point-spine.Bone->Position(),twist=Limbs[0].A-Limbs[1].A;OrthoNormalize(axis,twist);auto rotation=Mul(FromTo(Rotate(spine.Bone->Rotation(),spine.Twist),twist),spine.Bone->Rotation());float weight=static_cast<float>(double(i)/(Spines.size()-2)*TwistWeight);spine.Bone->Rotation(weight>=1?rotation:Lerp(spine.Bone->Rotation(),rotation,weight));}auto* neck=Spines.back().Bone;neck->Position(top);neck->Rotation(Mul(highPlane,neckRotation));for(auto& limb:Limbs){if(limb.Shoulder)limb.Shoulder->Rotation(Mul(FromTo(Rotate(limb.Shoulder->Rotation(),limb.ShoulderAxis),limb.A-limb.Shoulder->Position()),limb.Shoulder->Rotation()));limb.Upper->Position(limb.A);limb.Upper->Rotation(Mul(Plane(limb.A,limb.B,limb.C),limb.UpperFrame));limb.Lower->Rotation(Mul(Plane(limb.B,limb.C,limb.A),limb.LowerFrame));limb.End->Rotation(limb.Target->Rotation());}
    }
};
struct NativeEyeLook::Impl {
    struct Eye{NativeSceneNode* Bone{};Vector3 Forward{},Up{},CurrentUp{};Quaternion Rest{};float Horizontal=0,Vertical=0;bool Right=false;};
    NativeSceneNode* Root{};Parameter Settings;std::vector<Eye> Eyes;float HorizontalRate=0,VerticalRate=0;
    Impl(const Parameter& data,const std::unordered_map<std::string,NativeSceneNode*>& nodes,const std::unordered_map<std::string,NativeSceneNode*>& source){Root=nodes.at(data.String("rootNode"));Settings=At(data.Get("eyeTypeStates"),0);auto* originalRoot=source.at(data.String("rootNode"));for(auto& item:data.Get("eyeObjs").Children){auto* bone=nodes.at(item.String("eyeTransform"));auto* original=source.at(bone->Name);Require(original->Parent(),"Eye gaze source parent is missing.");auto basis=Mul(Inverse(original->Parent()->Rotation()),originalRoot->Rotation());auto forward=Rotate(basis,Unit(Vector(data.Get("headLookVector")))),up=Rotate(basis,Unit(Vector(data.Get("headUpVector"))));Eyes.push_back({bone,forward,up,up,bone->LocalRotation(),0,0,item.Float("eyeLR")!=0});}}
    float Bend(float value){float threshold=Settings.Float("thresholdAngleDifference"),multiplier=Settings.Float("bendingMultiplier"),limit=Settings.Float("maxAngleDifference");return std::max(std::max(0.f,std::abs(value)-threshold)*std::abs(multiplier),std::abs(value)-limit)*(value>=0?1.f:-1.f)*(multiplier>=0?1.f:-1.f);}
    static float SignedAngle(Vector3 from,Vector3 to,Vector3 axis){from-=Project(from,axis);to-=Project(to,axis);return Angle(from,to)*(Dot(axis,Cross(from,to))<0?-1.f:1.f);}
    void Step(float delta){auto target=Root->Position()+Root->TransformDirection({0,0,1})*Settings.Float("forntTagDis",50);float blend=delta<=0?1:std::clamp(delta*Settings.Float("leapSpeed",2.5f),0.f,1.f);for(size_t i=0;i<Eyes.size();++i){auto& eye=Eyes[i];eye.Bone->LocalRotation(eye.Rest);auto parent=eye.Bone->Parent()->Rotation();auto direction=Rotate(Inverse(parent),Unit(target-eye.Bone->Position()));float h=Bend(SignedAngle(eye.Forward,direction,eye.Up)),v=Bend(SignedAngle(direction-Project(direction,eye.Up),direction,Cross(eye.Up,direction))),minimum=Settings.Float("minBendingAngle"),maximum=Settings.Float("maxBendingAngle");h=std::clamp(h,eye.Right?-maximum:minimum,eye.Right?-minimum:maximum);v=std::clamp(v,Settings.Float("upBendingAngle"),Settings.Float("downBendingAngle"));eye.Horizontal=Lerp(eye.Horizontal,h,blend);eye.Vertical=Lerp(eye.Vertical,v,blend);auto forward=Rotate(Mul(AxisAngle(eye.Up,eye.Horizontal*.017453292519943295f),AxisAngle(Cross(eye.Up,eye.Forward),eye.Vertical*.017453292519943295f)),eye.Forward),up=eye.Up;OrthoNormalize(forward,up);eye.CurrentUp=Slerp(eye.CurrentUp,up,delta<=0?1:std::clamp(delta*5,0.f,1.f));OrthoNormalize(forward,eye.CurrentUp);auto correction=Mul(Mul(parent,LookRotation(forward,eye.CurrentUp)),Inverse(Mul(parent,LookRotation(eye.Forward,eye.Up))));eye.Bone->Rotation(Mul(correction,eye.Bone->Rotation()));if(!eye.Right)HorizontalRate=Lerp(-1.f,1.f,InverseLerp(minimum,maximum,eye.Horizontal));if(i==0)VerticalRate=eye.Vertical>=0?-InverseLerp(0,Settings.Float("downBendingAngle"),eye.Vertical):InverseLerp(0,Settings.Float("upBendingAngle"),eye.Vertical);}}
};
NativeIdleLimbs::NativeIdleLimbs(const Parameter& c,const std::unordered_map<std::string,NativeSceneNode*>& b,const std::unordered_map<std::string,NativeSceneNode*>& r,std::vector<std::string>& d):impl_(std::make_unique<Impl>(c,b,r,d)){}
NativeIdleLimbs::~NativeIdleLimbs()=default;void NativeIdleLimbs::RestoreInputPose(){impl_->RestoreInputPose();}void NativeIdleLimbs::Step(){impl_->Step();}
NativeEyeLook::NativeEyeLook(const Parameter& c,const std::unordered_map<std::string,NativeSceneNode*>& b,const std::unordered_map<std::string,NativeSceneNode*>& r):impl_(std::make_unique<Impl>(c,b,r)){}
NativeEyeLook::~NativeEyeLook()=default;void NativeEyeLook::Step(float delta){impl_->Step(delta);}float NativeEyeLook::HorizontalRate()const{return impl_->HorizontalRate;}float NativeEyeLook::VerticalRate()const{return impl_->VerticalRate;}
